:root {
  --bg: #1f2933;
  --card: #f5f7fa;
  --ink: #1f2933;
  --muted: #52606d;
  --accent: #2f855a;
  --accent-press: #276749;
  --line: #cbd2d9;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at top, #323f4b, var(--bg));
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 460px;
  background: var(--card);
  border-radius: 16px;
  padding: 28px 24px 32px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  letter-spacing: 0.01em;
}

.subtitle {
  margin: 6px 0 24px;
  color: var(--muted);
  font-size: 1rem;
}

.control {
  margin-bottom: 24px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
}

.control-row {
  display: flex;
  gap: 10px;
  align-items: stretch;
}

button,
input {
  font: inherit;
  border-radius: 10px;
  border: 2px solid var(--line);
  background: #fff;
  color: var(--ink);
  padding: 10px 12px;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

button {
  min-width: 48px;
  cursor: pointer;
  font-weight: 700;
  font-size: 1.2rem;
  line-height: 1;
}

button:hover {
  border-color: var(--accent);
  background: #eef7f1;
}

button:active {
  background: var(--accent-press);
  border-color: var(--accent-press);
  color: #fff;
  transform: translateY(1px);
}

input {
  flex: 1;
  min-width: 0;
  text-align: center;
  font-weight: 600;
  font-size: 1.15rem;
}

input:hover {
  border-color: var(--accent);
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}

.hint {
  margin: 8px 0 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.ingredients {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 2px solid var(--line);
}

.ingredients li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 12px 2px;
  border-bottom: 1px solid var(--line);
}

.ingredients li:last-child {
  border-bottom: none;
}

.name {
  min-width: 0;
  overflow-wrap: anywhere;
}

.amount {
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: var(--accent-press);
}

@media (max-width: 400px) {
  .card {
    padding: 22px 16px 26px;
  }
  h1 {
    font-size: 1.4rem;
  }
}

(function () {
  "use strict";

  var BASE_SERVINGS = 4;
  var MIN_SERVINGS = 1;
  var MAX_SERVINGS = 12;

  var RECIPE = [
    { name: "All-purpose flour", amount: 200, unit: "g" },
    { name: "Butter", amount: 100, unit: "g" },
    { name: "Sugar", amount: 80, unit: "g" },
    { name: "Eggs", amount: 2, unit: "" },
    { name: "Milk", amount: 150, unit: "ml" }
  ];

  var servingsInput = document.getElementById("servings");
  var decreaseBtn = document.getElementById("decrease");
  var increaseBtn = document.getElementById("increase");
  var list = document.getElementById("ingredients");

  function roundOne(value) {
    return Math.round((value + Number.EPSILON) * 10) / 10;
  }

  function clampServings(value) {
    var n = parseInt(value, 10);
    if (isNaN(n)) return BASE_SERVINGS;
    if (n < MIN_SERVINGS) return MIN_SERVINGS;
    if (n > MAX_SERVINGS) return MAX_SERVINGS;
    return n;
  }

  function formatAmount(value, unit) {
    var rounded = roundOne(value);
    var text = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
    return unit ? text + " " + unit : text;
  }

  function render() {
    var servings = clampServings(servingsInput.value);
    var factor = servings / BASE_SERVINGS;

    list.textContent = "";
    RECIPE.forEach(function (item) {
      var li = document.createElement("li");

      var name = document.createElement("span");
      name.className = "name";
      name.textContent = item.name;

      var amount = document.createElement("span");
      amount.className = "amount";
      amount.textContent = formatAmount(item.amount * factor, item.unit);

      li.appendChild(name);
      li.appendChild(amount);
      list.appendChild(li);
    });
  }

  function setServings(next) {
    var clamped = clampServings(next);
    servingsInput.value = String(clamped);
    render();
  }

  servingsInput.addEventListener("input", function () {
    var raw = servingsInput.value;
    if (raw === "") return;
    var n = parseInt(raw, 10);
    if (!isNaN(n) && n >= MIN_SERVINGS && n <= MAX_SERVINGS) {
      render();
    }
  });

  servingsInput.addEventListener("change", function () {
    setServings(servingsInput.value);
  });

  servingsInput.addEventListener("blur", function () {
    setServings(servingsInput.value);
  });

  decreaseBtn.addEventListener("click", function () {
    setServings(clampServings(servingsInput.value) - 1);
  });

  increaseBtn.addEventListener("click", function () {
    setServings(clampServings(servingsInput.value) + 1);
  });

  render();
})();
